'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(Number(v)||0), initials=n=>String(n||'Agent').split(' ').map(x=>x[0]).slice(0,2).join(''), today=()=>new Date().toLocaleDateString('en-CA');
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',contacts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3a4 4 0 0 1 0 8',leads:'M12 3v18 M3 12h18 M5 5l14 14 M5 19L19 5',deals:'M3 7h18v14H3z M8 7V3h8v4',properties:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',inbox:'M3 5h18v14H3z M3 5l9 8 9-8',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 11h18',tasks:'M9 6h12 M9 12h12 M9 18h12 M2 5l2 2 3-3 M2 11l2 2 3-3 M2 17l2 2 3-3',campaigns:'M3 10l18-7-7 18-4-7z M10 14L21 3',documents:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',reports:'M4 21V11h4v10 M10 21V6h4v15 M16 21V2h4v19',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M20 20l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',arrow:'M4 12h16 M14 6l6 6-6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',team:'M3 20v-3a4 4 0 0 1 4-4h3a4 4 0 0 1 4 4v3 M8 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M18 14a4 4 0 0 1 4 4v2',admin:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z',billing:'M2 5h20v14H2z M2 10h20 M5 15h4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${(paths[n]||paths.overview).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
const photos=['assets/hero.webp','assets/property-1.jpg','assets/property-2.jpg','assets/property-3.jpg'];
function readFavourites(){try{const v=JSON.parse(localStorage.getItem('estate-favourites')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
let state={user:null,workspace:null,csrf:'',records:[],public:{agents:[],properties:[]},integrations:{},section:'overview',demo:false,query:'',filter:'All',fav:readFavourites()}, toastTimer;
const sampleProperties=[['The West Coast Residence','West Vancouver',8950000,4,4.5,4210],['Cedar & Stone','North Vancouver',5880000,5,4,3640],['The Point Grey House','Vancouver',4250000,4,3.5,2980]].map((p,i)=>({id:'sample-'+i,workspace:'sample',kind:'property',data:{name:p[0],location:p[1],price:p[2],beds:p[3],baths:p[4],area:p[5],image:photos[i+1],type:'House',status:'For sale',description:'An architectural concept inspired by West Coast living. Expansive glazing, natural materials and considered interiors connect every room to the outdoors. This is a demonstration listing, not a property offered for sale.'}}));
function samples(){const names=['Sophie Chen','Priya Sharma','Noah Kim','Maya Patel','Daniel Park','Ethan Wilson','Isabella Rossi','Lucas Nguyen'];let rows=[...sampleProperties];names.forEach((n,i)=>{rows.push({id:'c'+i,kind:'contact',data:{name:n,email:n.toLowerCase().replace(' ','.')+'@example.com',type:i%3===0?'Seller':'Buyer',status:['New enquiry','In conversation','Showing booked','Offer submitted'][i%4],budget:1800000+i*200000,source:['Website','Referral','Open house'][i%3],notes:'Demonstration contact — sample data.'}});rows.push({id:'d'+i,kind:'deal',data:{name:n,type:i%3===0?'Seller':'Buyer',status:['New enquiry','In conversation','Showing booked','Offer submitted'][i%4],value:1800000+i*200000,due:today(),contact:'c'+i}})});rows.push({id:'a1',kind:'appointment',data:{name:'Property showing',date:today()+'T11:00',location:'West Vancouver',notes:'Sophie Chen'}},{id:'a2',kind:'appointment',data:{name:'Listing consultation',date:today()+'T14:00',location:'Office',notes:'Daniel Park'}},{id:'t1',kind:'task',data:{name:'Follow up with Ethan Wilson',due:today(),priority:'High',status:'Open',notes:'Prepare the property shortlist'}},{id:'t2',kind:'task',data:{name:'Check in with Olivia',due:today(),priority:'Normal',status:'Open',notes:'Discuss preferred neighbourhoods'}});return rows;}
function toast(t){$('#toast').className='toast';$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},4500)}
async function api(action,data){const opts=data!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(data)}:{};const r=await fetch('api.php?action='+action,opts);let b;try{b=await r.json()}catch{throw Error('Unexpected server response. Verify the PHP installation.')}if(!r.ok)throw Error(b.error||'Request failed');return b;}
async function refresh(){if(state.demo)return;const s=await api('session');Object.assign(state,s);if(s.user)state.records=await api('records');}
async function save(kind,data,id){if(state.demo){if(id){state.records=state.records.map(r=>r.id===id?{...r,data}:r)}else state.records.unshift({id:'demo-'+Date.now(),kind,data});toast('Demo updated in memory. Sign up to save your work.');return;}await api('save',{kind,data,...(id?{id}:{})});state.records=await api('records');toast('Saved successfully');}
const byKind=k=>state.records.filter(r=>r.kind===k), filtered=k=>byKind(k).filter(r=>(!state.query||JSON.stringify(r.data).toLowerCase().includes(state.query.toLowerCase()))&&(state.filter==='All'||r.data.status===state.filter||r.data.type===state.filter));
function nav(agent){return `<header class="topnav"><a class="brand" href="index.php">${esc(agent?.name||'E S T A T E')}<span>${esc(agent?.data?.brokerage||'EXCEPTIONAL PLACES. REAL CONNECTIONS.')}</span></a><nav class="navlinks"><a href="?page=properties">Properties</a><a href="?page=sell">Sell with us</a><a href="?page=agents">Find an agent</a><a href="?page=platform">For agents</a></nav><div class="navright"><button class="ghost" data-act="favourites" aria-label="Saved properties">♡ ${state.fav.length||''}</button>${state.user?'<a class="btn outline small" href="?view=workspace">My workspace ↗</a>':'<button class="btn outline small" data-act="auth">Agent sign in ↗</button>'}</div></header>`}
function footer(){return `<footer class="footer"><div><a class="brand" href="index.php">E S T A T E<span>REAL ESTATE, REIMAGINED</span></a><p>A place to find your next chapter.</p></div><div><a href="?page=properties">Properties</a><a href="?page=agents">Agents</a><a href="?page=platform">Join Estate</a><p>© ${new Date().getFullYear()} Estate. Listing information is supplied by individual agents.</p><a href="?page=privacy">Privacy</a><a href="?page=terms">Terms</a></div></footer>`}
function propertyCard(r){const d=r.data;return `<article class="property"><div class="propertyphoto"><a href="#" data-act="property" data-id="${esc(r.id)}"><img src="${esc(d.image||photos[1])}" alt="${esc(d.name)}" loading="lazy"></a><span class="tag">${r.id.startsWith('sample')?'Design example':esc(d.status||'For sale')}</span><button class="heart" data-act="heart" data-id="${esc(r.id)}" aria-label="Save ${esc(d.name)}">${state.fav.includes(r.id)?'♥':'♡'}</button></div><div class="propertybody"><a href="#" data-act="property" data-id="${esc(r.id)}"><div class="price">${money(d.price)}</div><h3>${esc(d.name)}</h3></a><p>${esc(d.location)}</p><div class="specs"><span>⌂ ${esc(d.beds||'—')} beds</span><span>♧ ${esc(d.baths||'—')} baths</span><span>△ ${Number(d.area||0).toLocaleString()} sq ft</span></div></div></article>`}
function available(){return state.public.properties.length?state.public.properties:sampleProperties}
function publicPage(){const page=new URLSearchParams(location.search).get('page')||'home',slug=new URLSearchParams(location.search).get('agent');if(slug)return agentPage(slug);let html='';if(page==='home'){html=`<section class="hero"><img class="heroimg" src="${photos[0]}" alt="A light-filled contemporary home with natural materials"><div class="herocopy"><div class="eyebrow">A MORE PERSONAL WAY HOME</div><h1>Exceptional homes.<br>Personal guidance.</h1><p>Thoughtful advice. Extraordinary properties.<br>A home for your next chapter.</p><a class="btn" href="?page=properties">Explore the collection ${icon('arrow')}</a></div><div class="herofoot">CURATED SPACES / CONSIDERED LIVING<br>Explore something exceptional ↓</div></section>${searchForm()}<section class="section"><div class="sectionhead"><div><div class="eyebrow muted">THE PROPERTY COLLECTION</div><h2>A collection worth discovering.</h2></div><a class="textlink" href="?page=properties">View all properties ↗</a></div>${!state.public.properties.length?'<p class="helper">Design preview · Sample properties and prices. No active listings have been published yet.</p>':''}<div class="propertygrid">${available().slice(0,3).map(propertyCard).join('')}</div></section><section class="band"><img src="${photos[3]}" alt="Contemporary home surrounded by greenery" loading="lazy"><div><div class="eyebrow muted">EXPERTISE WITH A PERSONAL TOUCH</div><h2>Your next chapter.<br>Our full attention.</h2><p>From your first conversation to the moment you receive the keys, find an agent who understands what home means to you.</p><div class="benefits"><div><span>Local knowledge</span><p>Guidance grounded in your community.</p></div></div><a class="btn" href="?page=agents">Meet your agent ${icon('arrow')}</a></div></section><section class="section"><div class="sectionhead"><div class="eyebrow muted">FOR REAL ESTATE PROFESSIONALS</div></div><div class="two"><h2>Your business.<br>Beautifully organized.</h2><div><p class="muted">Your own branded website, every client conversation, and every opportunity—together in one considered workspace.</p><a class="btn outline" href="?page=platform">Discover the platform ↗</a></div></div></section>`}else if(page==='properties'){html=`<section class="section"><div class="eyebrow muted">FIND YOUR NEXT CHAPTER</div><h1>The property collection.</h1>${searchForm(true)}<div id="propertyresults" class="spacer"></div></section>`}else if(page==='agents'){html=`<section class="section"><div class="eyebrow muted">PEOPLE BEHIND THE PROPERTIES</div><h1>Find your kind of expert.</h1><p class="muted">Local knowledge. Personal attention. Discover the agents who make it happen.</p><div class="agentgrid">${state.public.agents.map(a=>`<article class="agentcard"><div class="avatar big">${esc(initials(a.name))}</div><h2>${esc(a.name)}</h2><p class="muted">${esc(a.data.brokerage||'Independent real estate professional')}<br>${esc(a.data.area)}</p><a class="btn outline" href="?agent=${esc(a.slug)}">Meet ${esc(a.name.split(' ')[0])} ↗</a></article>`).join('')||'<div class="empty"><h3>A community taking shape.</h3><p>Approved agent profiles will appear here.</p><button data-act="register">Create your agent profile</button></div>'}</div></section>`}else if(page==='sell'){html=`<section class="band"><div><div class="eyebrow">YOUR HOME DESERVES A THOUGHTFUL APPROACH</div><h1>Make your<br>next move.</h1><p>Connect with a local agent to discuss your property, your timeline, and a marketing approach tailored to your home.</p><a class="btn" href="?page=agents">Find a selling agent →</a></div><img src="${photos[2]}" alt="Luxury home exterior"></section><section class="section"><div class="fullgrid">${[['01','A personal conversation','Share your goals and ask questions before deciding on the right agent.'],['02','A considered strategy','Discuss valuation, photography, presentation, and your marketing plan.'],['03','Guidance at every step','Stay connected through enquiries, showings, offers, and closing.']].map(x=>`<div class="panel"><div class="eyebrow muted">${x[0]}</div><h2>${x[1]}</h2><p>${x[2]}</p></div>`).join('')}</div></section>`}else if(page==='platform'){html=`<section class="section"><div class="eyebrow muted">THE REAL ESTATE WORKSPACE</div><h1>More personal.<br>Less paperwork.</h1><p class="muted">Your website, properties, clients, and opportunities. One beautifully organized place.</p><div class="actions"><button data-act="register">Create your workspace →</button><a class="btn outline" href="?view=workspace&demo=1">Explore the demo</a></div></section><section class="section" style="padding-top:0">${pricing(false)}</section>`}else{html=`<section class="section"><h1>${page==='privacy'?'Privacy information':'Platform terms'}</h1><div class="panel"><p>Estate provides agent websites and client-management tools. Each agent is responsible for the accuracy and authorization of their listings and for how they handle client information.</p><p>Contact enquiries are shared with the agent identified on the listing or profile. Your account uses a session cookie to keep you signed in. Saved-property preferences are stored on your device. Private workspace records are visible to authorized members of that workspace.</p><p>Contact the agent shown on the relevant profile for listing questions or data requests. The platform operator must add their legal business identity, privacy contact, retention policy, and applicable subscription terms before accepting paying customers.</p><p class="helper">Launch configuration required: this page is a general product notice, not a finalized legal policy.</p></div></section>`}$('#app').innerHTML=nav()+html+footer();if(page==='properties')renderPropertyResults();}
function searchForm(inline=false){const p=new URLSearchParams(location.search);return `<form id="searchform" class="searchbar" ${inline?'style="margin:25px 0;width:100%;box-shadow:none;border:1px solid var(--line)"':''}><label>Location<input name="location" placeholder="City or neighbourhood" value="${esc(p.get('location')||'')}"></label><label>Property type<select name="type"><option value="">Any type</option>${['House','Condo','Townhouse','Land'].map(t=>`<option ${p.get('type')===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Price range<select name="max"><option value="">Any price</option>${[1000000,2500000,5000000,10000000].map(v=>`<option value="${v}" ${p.get('max')==v?'selected':''}>Up to ${money(v)}</option>`).join('')}</select></label><button>Search ${icon('search')}</button></form>`}
function renderPropertyResults(){const p=new URLSearchParams(location.search);let rows=available().filter(r=>(!p.get('location')||(r.data.location+' '+r.data.name).toLowerCase().includes(p.get('location').toLowerCase()))&&(!p.get('type')||r.data.type===p.get('type'))&&(!p.get('max')||Number(r.data.price)<=Number(p.get('max'))));if(p.get('saved'))rows=rows.filter(r=>state.fav.includes(r.id));$('#propertyresults').innerHTML=`<div class="sectionhead"><p class="muted">${rows.length} ${state.public.properties.length?'properties':'design examples'} found</p><a class="textlink" href="?page=properties">Clear filters</a></div><div class="propertygrid">${rows.map(propertyCard).join('')}</div>${rows.length?'':'<div class="empty"><h3>No properties match yet.</h3><p>Try a different area or a wider price range.</p></div>'}`;}
function agentPage(slug){const a=state.public.agents.find(a=>a.slug===slug);if(!a){$('#app').innerHTML=nav()+'<section class="section"><h1>Profile not available.</h1><p>This profile may be unpublished or awaiting approval.</p><a class="btn" href="?page=agents">Browse agents</a></section>'+footer();return}$('#app').innerHTML=nav(a)+`<section class="hero"><img class="heroimg" src="${photos[0]}" alt="Contemporary coastal architectural illustration"><div class="herocopy"><div class="eyebrow">${esc(a.data.area||'LOCAL EXPERTISE')} · ${esc(a.data.brokerage||'REAL ESTATE')}</div><h1>${esc(a.data.headline||'Exceptional homes. Personal guidance.')}</h1><p>A personal approach to your next chapter.</p><button class="btn" data-act="enquire" data-id="${esc(a.id)}">Book a consultation →</button></div></section><section class="section"><div class="sectionhead"><div><div class="eyebrow muted">THE PROPERTY COLLECTION</div><h2>A collection worth discovering.</h2></div></div><div class="propertygrid">${state.public.properties.filter(p=>p.workspace===a.id).map(propertyCard).join('')||'<p class="muted">New listings will appear here. Contact me to discuss your search.</p>'}</div></section><section class="band"><img src="${photos[3]}" alt="Contemporary home design"><div><div class="eyebrow muted">YOUR LOCAL REAL ESTATE PROFESSIONAL</div><h2>Meet ${esc(a.name)}.</h2><p style="white-space:pre-line">${esc(a.data.bio||'Personal guidance for your next property journey.')}</p><p>${esc(a.data.brokerage)}<br>${esc(a.data.phone)}<br>${esc(a.data.email)}</p><button data-act="enquire" data-id="${esc(a.id)}">Let’s start a conversation →</button></div></section>`+footer();}

function modal(title,html){const d=$('#modal');d.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="ghost" data-act="close" aria-label="Close dialog">✕</button></div><div class="modalbody">${html}</div>`;if(!d.open)d.showModal();d.querySelector('input:not([type=hidden]),textarea,button')?.focus();}
function auth(mode='login'){modal(mode==='register'?'Your next chapter starts here.':mode==='forgot'?'Reset your password.':'Welcome back.',`<p class="muted">${mode==='register'?'Create your private agent workspace. Public profiles require administrator approval.':mode==='forgot'?'We’ll send a reset link if your account exists.':'Sign in to your Estate workspace.'}</p><form id="authform" data-mode="${mode}">${mode==='register'?'<label>Your name<input name="name" autocomplete="name" required maxlength="150"></label>':''}<label>Email address<input name="email" type="email" autocomplete="email" required></label>${mode!=='forgot'?`<label>Password<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="${mode==='register'?12:1}" required></label>`:''}<p class="error formmessage"></p><button style="width:100%">${mode==='register'?'Create workspace':mode==='forgot'?'Send reset link':'Sign in'} →</button></form><div class="authswitch">${mode==='register'?'<button class="ghost" data-act="auth">Already a member? Sign in</button>':'<button class="ghost" data-act="register">New to Estate? Create an account</button><br><button class="ghost" data-act="forgot">Forgot password?</button>'}</div>`)}
function showProperty(id){const r=[...state.public.properties,...sampleProperties,...byKind('property')].find(r=>r.id===id);if(!r)return;const d=r.data,a=state.public.agents.find(a=>a.id===r.workspace);modal(esc(d.name),`<img class="detailhero" src="${esc(d.image||photos[1])}" alt="${esc(d.name)}"><div class="spacer"><div class="price">${money(d.price)}</div><p class="muted">${esc(d.location)}</p><div class="specs"><span>${esc(d.beds||'—')} beds</span><span>${esc(d.baths||'—')} baths</span><span>${Number(d.area||0).toLocaleString()} sq ft</span></div><p style="white-space:pre-line">${esc(d.description)}</p>${d.images?`<div class="propertygrid">${d.images.split('\n').filter(x=>/^https:\/\//.test(x)||/^api\.php\?action=image&id=[a-f0-9]{32}$/.test(x)).map(x=>`<img style="width:100%;height:130px;object-fit:cover" src="${esc(x)}" alt="Property photograph" loading="lazy">`).join('')}</div>`:''}${a?`<p>Listed by <a class="textlink" href="?agent=${esc(a.slug)}">${esc(a.name)}</a></p><button data-act="enquire" data-id="${esc(a.id)}" data-property="${esc(r.id)}">Request a showing →</button>`:'<p class="helper">Demonstration listing. This property is not being offered for sale.</p>'}<button class="outline" data-act="heart" data-id="${esc(id)}">♡ Save property</button></div>`)}
function enquire(id,property=''){modal(property?'Arrange a private viewing.':'Let’s talk about your next move.',`<form id="enquiryform" data-workspace="${esc(id)}" data-property="${esc(property)}"><div class="fieldgrid"><label>Your name<input name="name" required maxlength="100"></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone" type="tel"></label><label>I’m looking to<select name="type"><option value="Buyer">Buy a property</option><option value="Seller">Sell a property</option></select></label><label class="wide">Your message<textarea name="message" required maxlength="3000" placeholder="Tell us what you have in mind, including preferred showing times."></textarea></label></div><input name="website" tabindex="-1" autocomplete="off" style="display:none"><p class="helper">Your details will be shared with this agent to respond to your enquiry.</p><p class="error formmessage"></p><button>Send enquiry →</button></form>`)}
const navigation=['overview','contacts','leads','deals','properties','inbox','calendar','tasks','campaigns','documents','reports'];
const titles={overview:'Overview',contacts:'Contacts',leads:'Leads',deals:'Deal pipeline',properties:'Properties',inbox:'Activity & inbox',calendar:'Calendar',tasks:'Tasks',campaigns:'Campaign drafts',documents:'Documents',reports:'Reports',settings:'Website & settings',team:'Team',billing:'Subscription',admin:'Platform admin'};
function workspace(){const name=state.workspace?.name||'Navjot Real Estate';$('#app').innerHTML=`<div class="workspace"><aside class="sidebar"><a class="brand" href="index.php">E S T A T E<span>YOUR AGENT WORKSPACE</span></a><div class="navgroup">WORKSPACE</div><nav class="sidenav">${navigation.map(n=>`<button data-act="section" data-id="${n}" class="${state.section===n?'active':''}">${icon(n)}${titles[n]}</button>`).join('')}</nav><div class="sidebottom"><nav class="sidenav">${['team','settings','billing',...(state.user?.role==='admin'?['admin']:[])].map(n=>`<button data-act="section" data-id="${n}" class="${state.section===n?'active':''}">${icon(n)}${titles[n]}</button>`).join('')}</nav><div class="mini"><div class="planbadge">${state.demo?'DEMONSTRATION':esc(state.workspace?.plan||'PROFESSIONAL').toUpperCase()}</div><p>Your business, beautifully organized.</p><a href="${state.workspace?.slug?'?agent='+esc(state.workspace.slug):'index.php'}">View your website ↗</a></div></div></aside><div class="workspacebody"><header class="worktop"><div style="display:flex;align-items:center"><button class="ghost menu-toggle" data-act="menu" aria-label="Toggle navigation">☰</button>${icon('search')}<input class="search" id="globalsearch" placeholder="Search contacts, properties, deals…" value="${esc(state.query)}" aria-label="Search workspace"></div><div class="right"><a class="textlink" href="index.php">View website ↗</a><button class="ghost" data-act="section" data-id="tasks" aria-label="View tasks">${icon('bell')}</button><div class="profile"><span class="avatar">${esc(initials(name))}</span><span>${esc(name)}<br><small class="muted">${state.demo?'Demo workspace':esc(state.user?.role||'Agent')}</small></span></div><button class="ghost" data-act="logout" aria-label="Sign out">↪</button></div></header>${state.demo?'<div class="notice">Interactive demo · Changes last only for this visit. <button class="ghost small" data-act="register">Create your own workspace →</button></div>':state.workspace?.status!=='approved'?'<div class="notice">Your CRM is ready. Public profile publication is awaiting administrator approval.</div>':''}<main class="workmain" id="workcontent"></main></div></div>`;workContent();}
function head(title,sub,kind){return `<div class="workhead"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${kind?`<button class="outline" data-act="export" data-id="${kind}">Export CSV</button><button data-act="new" data-id="${kind}">+ Add ${kind==='property'?'property':kind}</button>`:''}</div></div>`;}
function metrics(){const open=byKind('deal').filter(r=>r.data.status!=='Closed'&&r.data.status!=='Lost'),v=open.reduce((s,r)=>s+Number(r.data.value||0),0);return `<div class="metrics">${[['New enquiries',byKind('contact').filter(r=>r.data.status==='New enquiry').length,'leads','Ready for a personal follow-up'],['Active clients',byKind('contact').length,'contacts','Contacts in your workspace'],['Upcoming showings',byKind('appointment').filter(r=>(r.data.date||'')>=today()&&r.data.status!=='Cancelled').length,'calendar','Scheduled appointments'],['Open pipeline',money(v),'deals',open.length+' active opportunities']].map(x=>`<div class="metric"><div class="row"><span>${x[0]}</span><span class="iconbox">${icon(x[2])}</span></div><strong>${x[1]}</strong><small>${x[3]}</small></div>`).join('')}</div>`;}
const stages=['New enquiry','In conversation','Showing booked','Offer submitted','Closed','Lost'];
function pipeline(compact=false){return `<div class="pipeline" ${!compact?'style="grid-template-columns:repeat(6,minmax(185px,1fr))"':''}>${stages.slice(0,compact?4:6).map(s=>{const rows=filtered('deal').filter(r=>(r.data.status||'New enquiry')===s);return `<div class="column" data-stage="${s}"><div class="columnhead">${s}<span>${rows.length}</span></div>${rows.map(r=>`<div class="dealcard" draggable="true" data-id="${esc(r.id)}"><div class="row"><span class="avatar">${esc(initials(r.data.name))}</span><div><a href="#" data-act="edit" data-id="${esc(r.id)}">${esc(r.data.name)}</a><br><span class="tag ${r.data.type==='Seller'?'gold':'blue'}">${esc(r.data.type||'Buyer')}</span></div></div><p>${money(r.data.value)}</p><p class="muted">${r.data.due?'Follow up · '+esc(r.data.due):'No follow-up scheduled'}</p><select aria-label="Stage for ${esc(r.data.name)}" data-stage-id="${esc(r.id)}">${stages.map(t=>`<option ${t===s?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')||'<div class="empty" style="padding:24px 0;font-size:10px">No deals yet</div>'}</div>`}).join('')}</div>`;}
function taskrow(r){return `<div class="taskrow"><button class="check ${r.data.status==='Done'?'checked':''}" data-act="toggle-task" data-id="${esc(r.id)}" aria-label="Toggle ${esc(r.data.name)}">${r.data.status==='Done'?'✓':''}</button><div><a href="#" data-act="edit" data-id="${esc(r.id)}">${esc(r.data.name)}</a><p>${esc(r.data.notes||r.data.priority||'')}</p><p class="${r.data.due&&r.data.due<today()?'error':''}">${esc(r.data.due||'No due date')}</p></div></div>`}
function appt(r){return `<div class="appointment"><span class="time">${esc((r.data.date||'').split('T')[1]||'—')}</span><div><a href="#" data-act="edit" data-id="${esc(r.id)}">${esc(r.data.name)}</a><p>${esc(r.data.location||'Location to be confirmed')}</p><p>${esc((r.data.date||'').split('T')[0])}</p></div></div>`}
function contactsTable(rows){return `<div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Budget</th><th>Status</th><th>Source</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="row"><span class="avatar">${esc(initials(r.data.name))}</span><div><a href="#" data-act="edit" data-id="${esc(r.id)}">${esc(r.data.name)}</a><div class="helper">${esc(r.data.email||'')}</div></div></div></td><td><span class="tag ${r.data.type==='Seller'?'gold':'blue'}">${esc(r.data.type||'Buyer')}</span></td><td>${r.data.budget?money(r.data.budget):'—'}</td><td>${esc(r.data.status||'New enquiry')}</td><td>${esc(r.data.source||'Manual')}</td><td><button class="ghost small" data-act="edit" data-id="${esc(r.id)}">Edit ↗</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('Your next connection starts here.','Add a contact or receive an enquiry from your website.','contact')}`}
function empty(title,sub,kind){return `<div class="empty"><h3>${title}</h3><p>${sub}</p>${kind?`<button class="outline small" data-act="new" data-id="${kind}">+ Add ${kind}</button>`:''}</div>`}
function toolbar(filters=[]){return `<div class="toolbar"><input id="recordsearch" aria-label="Search records" placeholder="Search this workspace…" value="${esc(state.query)}">${filters.length?`<select id="recordfilter" aria-label="Filter records">${['All',...filters].map(t=>`<option ${state.filter===t?'selected':''}>${t}</option>`).join('')}</select>`:''}</div>`}
function workContent(){const c=$('#workcontent'),s=state.section;let h='';if(s==='overview'){const first=(state.user?.name||'Navjot').split(' ')[0];h=head(`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${esc(first)}.`,"A little clarity for your next big move.",'contact')+metrics()+`<div class="dashboardgrid"><div class="panel"><div class="panelhead"><h3>Deal pipeline</h3><button class="ghost small" data-act="section" data-id="deals">All deals ↗</button></div>${pipeline(true)}</div><div class="stack"><div class="panel"><div class="panelhead"><h3>Your schedule</h3>${icon('calendar')}</div>${byKind('appointment').filter(r=>(r.data.date||'')>=today()&&r.data.status!=='Cancelled').sort((a,b)=>a.data.date.localeCompare(b.data.date)).slice(0,3).map(appt).join('')||'<p class="helper">No upcoming appointments. Make room for your next opportunity.</p>'}</div><div class="panel"><div class="panelhead"><h3>Follow-ups</h3><button class="ghost small" data-act="section" data-id="tasks">View all ↗</button></div>${byKind('task').filter(r=>r.data.status!=='Done').slice(0,3).map(taskrow).join('')||'<p class="helper">You’re all caught up.</p>'}</div></div></div><div class="panel recent"><div class="panelhead"><h3>Recent connections</h3><button class="ghost small" data-act="section" data-id="contacts">View contacts ↗</button></div>${contactsTable(byKind('contact').slice(0,5))}</div>`}else if(s==='contacts'||s==='leads'){h=head(titles[s],s==='contacts'?'Every relationship, thoughtfully organized.':'Turn the first conversation into the next opportunity.','contact')+toolbar(['Buyer','Seller',...stages])+`<div class="panel">${contactsTable(filtered('contact').filter(r=>s!=='leads'||!['Closed','Lost'].includes(r.data.status)))}</div>`}else if(s==='deals'){h=head('Every opportunity. In view.','Move deals between stages, or open a card to update its details.','deal')+metrics()+pipeline()}else if(s==='properties'){h=head('Your property collection.','Manage presentation, availability, and public visibility.','property')+toolbar(['For sale','For rent','Pending','Sold'])+`<div class="propertygrid">${filtered('property').map(r=>`<div><div class="property">${propertyCard(r).replace(/<article class="property">|<\/article>/g,'')}</div><div class="listrow"><span class="tag">${r.data.published?'Published':'Draft'}</span><button class="outline small" data-act="edit" data-id="${esc(r.id)}">Manage listing ↗</button></div></div>`).join('')}</div>${byKind('property').length?'':empty('Make a remarkable first impression.','Add your first property with photography and the details buyers need.','property')}`}else if(s==='calendar'){h=head('A little space for everything.','Your appointments, showings, and client conversations.','appointment')+toolbar()+`<div class="panel">${filtered('appointment').sort((a,b)=>(a.data.date||'').localeCompare(b.data.date||'')).map(r=>`<div class="listrow">${appt(r)}<div><span class="tag">${esc(r.data.status||'Scheduled')}</span> <button class="outline small" data-act="ics" data-id="${esc(r.id)}">Add to calendar</button></div></div>`).join('')||empty('Your calendar is clear.','Add a showing or client meeting.','appointment')}</div>`}else if(s==='tasks'){h=head('Stay one step ahead.','Keep promises, follow up, and focus on what matters.','task')+toolbar(['Open','Done'])+`<div class="panel">${filtered('task').sort((a,b)=>(a.data.due||'9999').localeCompare(b.data.due||'9999')).map(taskrow).join('')||empty('Nothing on your list.','Create a task to plan your next step.','task')}</div>`}else if(s==='inbox'){h=head('Every conversation counts.','Log calls, meetings, emails, and client notes in one timeline.','activity')+`<div class="notice">Communication log · Connected mailbox synchronization and SMS delivery are not enabled.</div>`+toolbar()+`<div class="panel spacer">${filtered('activity').map(r=>`<div class="listrow"><div><span class="tag">${esc(r.data.type||'Note')}</span><h3 class="spacer">${esc(r.data.name)}</h3><p>${esc(r.data.notes)}</p><p>${esc(r.data.date||'')}</p></div><button class="outline small" data-act="edit" data-id="${esc(r.id)}">Edit</button></div>`).join('')||empty('Build a complete picture.','Log your first client conversation.','activity')}</div>`}else if(s==='campaigns'){h=head('A thoughtful way to stay in touch.','Prepare campaign copy and manage draft marketing plans.','campaign')+'<div class="notice">Draft workspace · Campaign sending and unsubscribe delivery infrastructure are not connected.</div>'+`<div class="fullgrid spacer">${filtered('campaign').map(r=>`<div class="panel"><span class="tag">Draft</span><h2 class="spacer" style="font-size:30px">${esc(r.data.name)}</h2><p>${esc(r.data.subject||'')}</p><p>${esc(r.data.audience||'All contacts')}</p><button class="outline small" data-act="edit" data-id="${esc(r.id)}">Edit draft ↗</button></div>`).join('')}</div>${byKind('campaign').length?'':empty('Make your next message count.','Create a draft to plan your next announcement.','campaign')}`}else if(s==='documents'){h=head('Everything in its place.','Private workspace files. JPEG, PNG, WebP, and PDF up to 10 MB per file.')+`<div class="panel"><label>Upload a document or property image<input id="uploadfile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><p class="helper">Workspace allowance: 500 MB. Uploaded images become public only when used on a published listing.</p></div><div class="panel spacer">${byKind('document').map(r=>`<div class="listrow"><div><h3>${esc(r.data.name)}</h3><p>${esc(r.data.mime||'Document')} · ${Math.round(Number(r.data.size||0)/1024)} KB</p></div><div class="actions">${r.data.fileId?`<a class="btn outline small" href="api.php?action=download&id=${esc(r.data.fileId)}">Download</a>${String(r.data.mime).startsWith('image/')?`<button class="outline small" data-act="copyimage" data-id="${esc(r.data.fileId)}">Copy image link</button>`:''}`:''}</div></div>`).join('')||empty('Your document library is ready.','Upload a file to keep it available to your workspace.')}</div>`}else if(s==='reports'){h=head('A clearer view of your business.','Live summaries calculated from your workspace records.')+metrics()+`<div class="two"><div class="panel"><h2 style="font-size:30px">Where connections begin</h2>${['Website','Referral','Open house','Social media','Manual'].map(t=>{const n=byKind('contact').filter(r=>(r.data.source||'Manual')===t).length;return `<div class="barrow"><span>${t}</span><div class="bar"><span style="width:${n/Math.max(byKind('contact').length,1)*100}%"></span></div><span>${n}</span></div>`}).join('')}</div><div class="panel"><h2 style="font-size:30px">Deal outcomes</h2>${stages.map(t=>{const n=byKind('deal').filter(r=>r.data.status===t).length;return `<div class="barrow"><span>${t}</span><div class="bar"><span style="width:${n/Math.max(byKind('deal').length,1)*100}%"></span></div><span>${n}</span></div>`}).join('')}</div></div><div class="panel spacer"><h3>Recorded commission</h3><div class="price">${money(byKind('deal').filter(r=>r.data.status==='Closed').reduce((s,r)=>s+Number(r.data.commission||0),0))}</div><p class="helper">Based on commission values entered on closed deals. This is not an accounting statement.</p></div>`}else if(s==='settings'){h=settingsPage()}else if(s==='billing'){h=head('Room for your next chapter.','Choose the workspace that fits your business.')+`<div class="notice">Current plan: ${esc(state.workspace?.plan||'Professional')} · ${esc(state.workspace?.subscription_status||'Demo')}. ${state.integrations.billing?'Checkout is connected.':'Payments are not connected. No card is required or charged.'}</div><div class="spacer">${pricing(true)}</div>`}else if(s==='team'){h=head('Better, together.','Team members share this workspace’s records. Separate agent accounts remain private.')+`<button data-act="teamadd">+ Add team member</button><div id="teamresults" class="panel spacer"><p class="muted">Loading team…</p></div>`;loadTeam()}else if(s==='admin'){h=head('Your platform, at a glance.','Approve agent profiles and manage workspace access.')+'<div id="adminresults" class="panel">Loading workspaces…</div>';loadAdmin()}c.innerHTML=h;}
function pricing(internal){return `<div class="pricing">${[['Starter',49,'A considered online presence',['Branded agent profile','Property publishing','Contacts and enquiry tracking']],['Professional',99,'Your everyday real estate workspace',['Everything in Starter','Deals, tasks and appointments','Documents and reporting']],['Team',249,'A shared workspace for your team',['Everything in Professional','Up to five team members','Owner-managed team access']]].map((p,i)=>`<div class="panel ${i===1?'featured':''}"><span class="eyebrow">${p[0]}</span><h3 class="spacer">${p[2]}</h3><div class="amount">$${p[1]} <small>CAD / month</small></div><ul>${p[3].map(x=>`<li>${x}</li>`).join('')}</ul><button class="${i===1?'':'outline'}" data-act="${internal?'checkout':'register'}" data-id="${p[0]}">${internal&&state.integrations.billing?'Choose plan':'Get started'} →</button><p class="helper spacer">${internal&&!state.integrations.billing?'Billing configuration required.':'Proposed launch pricing. Taxes and external services additional.'}</p></div>`).join('')}</div>${internal&&state.integrations.billing?'<button class="outline spacer" data-act="billingportal">Manage billing & cancellation ↗</button>':''}`}
function settingsPage(){const d=state.workspace?.data||{};return head('Make it unmistakably yours.','Your profile and published properties appear on your agent website.')+`<div class="settingsgrid"><form id="settingsform" class="panel"><div class="fieldgrid"><label>Business / agent name<input name="name" value="${esc(state.workspace?.name||'Navjot Real Estate')}" required></label><label>Brokerage<input name="brokerage" value="${esc(d.brokerage)}"></label><label class="wide">Homepage headline<input name="headline" value="${esc(d.headline||'Exceptional homes. Personal guidance.')}"></label><label>Service area<input name="area" value="${esc(d.area||'Vancouver')}"></label><label>Email<input name="email" type="email" value="${esc(d.email||state.user?.email)}"></label><label>Phone<input name="phone" value="${esc(d.phone)}"></label><label class="wide">Biography<textarea name="bio">${esc(d.bio)}</textarea></label><label class="wide checkboxlabel"><input type="checkbox" name="published" ${d.published?'checked':''}>Publish my agent profile once approved</label></div><p class="error formmessage"></p><button>Save website settings</button>${state.workspace?.slug?`<a class="btn outline" href="?agent=${esc(state.workspace.slug)}">View profile ↗</a>`:''}</form><div class="stack"><div class="panel"><h3>Connection status</h3>${[['Listing feeds','Not connected'],['Custom domain','Not configured'],['SMS & calling','Not connected'],['Payment processing',state.integrations.billing?'Configured':'Not connected'],['Password reset email',state.integrations.email?'Configured':'Not connected']].map(x=>`<div class="listrow"><span>${x[0]}</span><span class="tag">${x[1]}</span></div>`).join('')}<p class="helper spacer">Manual listing management and CRM storage are available. Additional integrations require provider accounts and configuration.</p></div><form class="panel" id="passwordform"><h3>Change password</h3><label>Current password<input type="password" name="current" required autocomplete="current-password"></label><label>New password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><p class="error formmessage"></p><button class="outline small">Update password</button></form></div></div>`}
const fields={contact:[['name','Full name'],['email','Email','email'],['phone','Phone','tel'],['type','Client type',['Buyer','Seller','Investor','Other']],['status','Status',stages],['budget','Budget (CAD)','number'],['location','Preferred areas'],['source','Source',['Manual','Website','Referral','Open house','Social media']],['notes','Notes','textarea']],deal:[['name','Deal / client name'],['type','Type',['Buyer','Seller']],['status','Stage',stages],['value','Property value (CAD)','number'],['commission','Expected commission (CAD)','number'],['contact','Client','contacts'],['due','Next follow-up','date'],['notes','Transaction notes & conditions','textarea']],property:[['name','Property title'],['location','Address / area'],['price','Price (CAD)','number'],['type','Property type',['House','Condo','Townhouse','Land']],['status','Availability',['For sale','For rent','Pending','Sold']],['beds','Bedrooms','number'],['baths','Bathrooms','number'],['area','Floor area (sq ft)','number'],['image','Cover image URL'],['images','Gallery image URLs (one per line)','textarea'],['description','Property description','textarea'],['published','Publish this listing','checkbox']],task:[['name','Task'],['contact','Linked client','contacts'],['due','Due date','date'],['priority','Priority',['Normal','High','Low']],['status','Status',['Open','Done']],['notes','Notes','textarea']],appointment:[['name','Appointment title'],['contact','Client','contacts'],['date','Date & time (your local time)','datetime-local'],['location','Location'],['status','Status',['Scheduled','Confirmed','Completed','Cancelled']],['notes','Notes','textarea']],activity:[['name','Subject'],['contact','Client','contacts'],['type','Activity type',['Note','Call','Email','Meeting']],['date','Date & time','datetime-local'],['notes','Conversation notes','textarea']],campaign:[['name','Campaign name'],['subject','Email subject'],['audience','Audience',['All contacts','Buyers','Sellers','Investors']],['notes','Message draft','textarea']]};
function field([key,label,type],data){const v=data[key]??'';let el;if(Array.isArray(type))el=`<select name="${key}">${type.map(t=>`<option ${v===t?'selected':''}>${t}</option>`).join('')}</select>`;else if(type==='contacts')el=`<select name="${key}"><option value="">No linked client</option>${byKind('contact').map(r=>`<option value="${esc(r.id)}" ${v===r.id?'selected':''}>${esc(r.data.name)}</option>`).join('')}</select>`;else if(type==='textarea')el=`<textarea name="${key}" maxlength="10000">${esc(v)}</textarea>`;else if(type==='checkbox')el=`<input type="checkbox" name="${key}" ${v?'checked':''}>`;else el=`<input name="${key}" type="${type||'text'}" value="${esc(v)}" ${key==='name'?'required maxlength="200"':''} ${type==='number'?'min="0" step="any"':''}>`;return `<label class="${type==='textarea'?'wide':type==='checkbox'?'wide checkboxlabel':''}">${type==='checkbox'?el+label:label+el}</label>`}
function editor(kind,id){const rec=id?state.records.find(r=>r.id===id):null;if(rec)kind=rec.kind;const data=rec?.data||{};if(!fields[kind])return;let linked='';if(kind==='contact'&&id){const rel=state.records.filter(r=>r.data.contact===id);linked=`<div class="panel spacer"><h3>Client timeline</h3>${rel.map(r=>`<div class="listrow"><span>${esc(r.data.name)}</span><span class="tag">${esc(r.kind)}</span></div>`).join('')||'<p class="helper">Link tasks, deals, appointments, and activities to this contact to see them here.</p>'}</div>`}modal((id?'Edit ':'Add ')+esc(kind==='property'?'property':kind),`<form id="recordform" data-kind="${kind}" data-id="${esc(id||'')}"><div class="fieldgrid">${fields[kind].map(f=>field(f,data)).join('')}</div>${kind==='property'?'<p class="helper">Upload images in Documents, then copy an image link here. Only publish listings you are authorized to display.</p>':''}<p class="error formmessage"></p><div class="modalfoot">${id?`<button type="button" class="ghost danger" data-act="delete" data-id="${esc(id)}">Delete record</button>`:'<span></span>'}<div><button type="button" class="outline" data-act="close">Cancel</button> <button>Save ${kind}</button></div></div></form>${linked}`)}
async function loadTeam(){try{const rows=state.demo?[{id:'demo',name:'Navjot',email:'agent@example.com',role:'owner',active:1}]:await api('team');if(!$('#teamresults'))return;$('#teamresults').innerHTML=`<div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${esc(r.role)}</td><td>${r.role==='agent'?`<button class="outline small" data-act="teamtoggle" data-id="${esc(r.id)}" data-active="${r.active?0:1}">${r.active?'Disable':'Enable'}</button>`:'Owner'}</td></tr>`).join('')}</tbody></table></div>`}catch(e){toast(e.message)}}
async function loadAdmin(){try{const d=await api('admin');if(!$('#adminresults'))return;$('#adminresults').innerHTML=`<div class="metrics"><div class="metric"><span>Workspaces</span><strong>${d.workspaces.length}</strong></div><div class="metric"><span>Pending approval</span><strong>${d.workspaces.filter(w=>w.status==='pending').length}</strong></div><div class="metric"><span>Accounts</span><strong>${d.users.length}</strong></div><div class="metric"><span>Active subscriptions</span><strong>${d.workspaces.filter(w=>w.subscription_status==='active').length}</strong></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Workspace</th><th>Plan</th><th>Billing status</th><th>Publication approval</th></tr></thead><tbody>${d.workspaces.map(w=>`<tr><td>${esc(w.name)}<div class="helper">${esc(w.created)}</div></td><td>${esc(w.plan)}</td><td>${esc(w.subscription_status)}</td><td><select data-admin-id="${esc(w.id)}">${['pending','approved','suspended'].map(s=>`<option ${s===w.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`}catch(e){toast(e.message)}}
function download(name,text,mime='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(kind){const rows=byKind(kind),keys=[...new Set(rows.flatMap(r=>Object.keys(r.data)))];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download(kind+'-export.csv',[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r.data[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Export downloaded')}
async function init(){try{await refresh();state.public=await api('public')}catch(e){state.connectionError=e.message}const p=new URLSearchParams(location.search);if(p.get('demo')==='1'){state.demo=true;state.records=samples();state.user={name:'Navjot',role:'owner',email:'navjot@example.com'};state.workspace={name:'Navjot Real Estate',data:{},plan:'Professional'}}if(p.get('view')==='workspace'){if(state.user)workspace();else{publicPage();auth();}}else publicPage();if(p.get('reset'))modal('Choose a new password.',`<form id="resetform"><label>New password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label><p class="error formmessage"></p><button>Reset password</button></form>`);if(state.connectionError)toast(state.connectionError);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el)return;e.preventDefault();const a=el.dataset.act,id=el.dataset.id;try{
 if(a==='close')$('#modal').close();if(a==='auth')auth();if(a==='register')auth('register');if(a==='forgot')auth('forgot');if(a==='property')showProperty(id);if(a==='enquire')enquire(id,el.dataset.property);if(a==='favourites')location.href='?page=properties&saved=1';if(a==='heart'){state.fav=state.fav.includes(id)?state.fav.filter(x=>x!==id):[...state.fav,id];localStorage.setItem('estate-favourites',JSON.stringify(state.fav));if(el.classList.contains('heart'))el.textContent=state.fav.includes(id)?'♥':'♡';toast(state.fav.includes(id)?'Saved to your shortlist':'Removed from shortlist');}if(a==='section'){state.section=id;state.query='';state.filter='All';workspace();}if(a==='menu')$('.sidebar').classList.toggle('open');if(a==='new')editor(id);if(a==='edit')editor('',id);if(a==='logout'){if(!state.demo)await api('logout',{});location.href='index.php';}if(a==='delete'){if(!confirm('Permanently delete this record?'))return;if(state.demo)state.records=state.records.filter(r=>r.id!==id);else{await api('delete',{id});state.records=await api('records');}$('#modal').close();workContent();toast('Record deleted');}if(a==='toggle-task'){const r=state.records.find(r=>r.id===id);await save('task',{...r.data,status:r.data.status==='Done'?'Open':'Done'},id);workContent();}if(a==='export')exportCSV(id);if(a==='copyimage'){const text='api.php?action=image&id='+id;try{await navigator.clipboard.writeText(text);toast('Image link copied')}catch{modal('Image link',`<input value="${text}" readonly><p class="helper">Copy this link into your property’s cover image field.</p>`);}}if(a==='ics'){const r=state.records.find(r=>r.id===id),d=r.data;const escapeICS=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');const date=String(d.date||'').replace(/[-:]/g,'')+'00';download('appointment.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Estate//Calendar//EN\r\nBEGIN:VEVENT\r\nUID:${r.id}@estate\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').split('.')[0]}Z\r\nDTSTART:${date}\r\nSUMMARY:${escapeICS(d.name)}\r\nLOCATION:${escapeICS(d.location)}\r\nDESCRIPTION:${escapeICS(d.notes)}\r\nEND:VEVENT\r\nEND:VCALENDAR`,'text/calendar');}if(a==='teamadd'){modal('Grow your team.',`<p class="helper">Members can view and edit all records in this workspace. Send their temporary password securely and ask them to change it after signing in.</p><form id="teamform"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Temporary password<input name="password" type="password" minlength="12" required></label><p class="error formmessage"></p><button>Create team account</button></form>`)}if(a==='teamtoggle'){await api('team_toggle',{id,active:el.dataset.active==='1'});loadTeam()}if(a==='checkout'||a==='billingportal'){if(state.demo||!state.integrations.billing){toast('Payment processing is not connected. No charge has been made.');return}const r=await api(a==='checkout'?'checkout':'billing_portal',a==='checkout'?{plan:id}:{});location.href=r.url;}
}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const vals=Object.fromEntries(new FormData(f)),btn=f.querySelector('button:not([type=button])');if(btn)btn.disabled=true;const err=f.querySelector('.formmessage');if(err)err.textContent='';try{
 if(f.id==='searchform'){const p=new URLSearchParams({page:'properties',...vals});location.href='?'+p;return}
 if(f.id==='authform'){if(state.connectionError)throw Error(state.connectionError);await api(f.dataset.mode,vals);if(f.dataset.mode==='forgot'){toast('If the account exists, a reset email has been requested.');$('#modal').close()}else location.href='?view=workspace';}
 if(f.id==='recordform'){for(const input of f.querySelectorAll('input[type=checkbox]'))vals[input.name]=input.checked;await save(f.dataset.kind,vals,f.dataset.id||undefined);$('#modal').close();workContent();}
 if(f.id==='settingsform'){vals.published=!!f.elements.published.checked;if(state.demo){state.workspace={...state.workspace,name:vals.name,data:vals};toast('Demo settings updated for this visit')}else{await api('settings',vals);await refresh();toast('Website settings saved')}workspace();}
 if(f.id==='passwordform'){if(state.demo)throw Error('Password changes are unavailable in the demo');await api('password',vals);f.reset();toast('Password updated')}
 if(f.id==='enquiryform'){await api('enquiry',{...vals,workspace:f.dataset.workspace,property:f.dataset.property});modal('Your enquiry is on its way.', '<p>The agent has received your message in their private workspace.</p><button data-act="close">Done</button>')}
 if(f.id==='teamform'){if(state.demo)throw Error('Create a workspace to add team members');await api('team_add',vals);$('#modal').close();loadTeam();toast('Team member created')}
 if(f.id==='resetform'){await api('reset',{...vals,token:new URLSearchParams(location.search).get('reset')});history.replaceState({},'','index.php');auth();toast('Password reset. Sign in with your new password.')}
}catch(ex){if(err)err.textContent=ex.message;else toast(ex.message)}finally{if(btn)btn.disabled=false}});
let searchTimer;document.addEventListener('input',e=>{if(['globalsearch','recordsearch'].includes(e.target.id)){clearTimeout(searchTimer);const id=e.target.id,pos=e.target.selectionStart;state.query=e.target.value;searchTimer=setTimeout(()=>{if(state.section==='overview')state.section='contacts';workContent();const input=$('#'+id);if(input&&id==='recordsearch'){input.focus();input.setSelectionRange(pos,pos)}},220)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='recordfilter'){state.filter=e.target.value;workContent()}if(e.target.dataset.stageId){const r=state.records.find(r=>r.id===e.target.dataset.stageId);await save('deal',{...r.data,status:e.target.value},r.id);workContent()}if(e.target.dataset.adminId){await api('admin_update',{id:e.target.dataset.adminId,status:e.target.value});toast('Workspace access updated')}if(e.target.id==='uploadfile'){if(state.demo)throw Error('Sign up to upload and store files');const file=e.target.files[0];if(!file)return;const f=new FormData();f.append('file',file);toast('Uploading file…');const r=await fetch('api.php?action=upload',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:f}),b=await r.json();if(!r.ok)throw Error(b.error);state.records=await api('records');workContent();toast('File uploaded securely')}}catch(ex){toast(ex.message)}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.dealcard');if(card)e.dataTransfer.setData('text/plain',card.dataset.id)});document.addEventListener('dragover',e=>{if(e.target.closest('[data-stage]'))e.preventDefault()});document.addEventListener('drop',async e=>{const c=e.target.closest('[data-stage]');if(!c)return;e.preventDefault();const r=state.records.find(r=>r.id===e.dataTransfer.getData('text/plain'));if(!r||r.kind!=='deal')return;try{await save('deal',{...r.data,status:c.dataset.stage},r.id);workContent()}catch(ex){toast(ex.message)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});init();
